cat > reports/TourismTaxReport.java <<'EOF'
package hotel.reports;

import hotel.reservations.PriceCalculator;
import hotel.reservations.Reservation;
import hotel.reservations.ReservationStore;
import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** The tourism tax the city charges on the paid reservations that start in a given month (CSV). */
public final class TourismTaxReport {

    private final ReservationStore store;
    private final BigDecimal taxPerGuestNight;

    public TourismTaxReport(ReservationStore store, BigDecimal taxPerGuestNight) {
        this.store = store;
        this.taxPerGuestNight = taxPerGuestNight;
    }

    public String generate(YearMonth month) {
        List<Reservation> taxed = new ArrayList<>();
        for (Reservation reservation : store.all()) {
            if (reservation.isPaid() && YearMonth.from(reservation.checkIn()).equals(month)) {
                taxed.add(reservation);
            }
        }
        taxed.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));

        List<String> rows = new ArrayList<>();
        BigDecimal total = PriceCalculator.cents(BigDecimal.ZERO);
        for (Reservation reservation : taxed) {
            int nights = reservation.price().nights();
            BigDecimal tax = PriceCalculator.cents(taxPerGuestNight.multiply(BigDecimal.valueOf((long) reservation.guests() * nights)));
            rows.add(reservation.id() + "," + reservation.roomNumber() + "," + reservation.checkIn() + ","
                    + reservation.checkOut() + "," + reservation.guests() + "," + nights + ","
                    + tax.toPlainString());
            total = total.add(tax);
        }
        return CsvReport.render("tourism-tax", month.toString(),
                "reservation,room,check_in,check_out,guests,nights,tax", rows, "total," + total.toPlainString());
    }
}
EOF
cat > reports/RatePlanReport.java <<'EOF'
package hotel.reports;

import hotel.reservations.PriceCalculator;
import hotel.reservations.RatePlan;
import hotel.reservations.Reservation;
import hotel.reservations.ReservationStore;
import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/**
 * How many reservations and how much money each rate plan brought, counting the same reservations as the
 * revenue report: those that start in the month and left money with the inn (CSV).
 */
public final class RatePlanReport {

    private final ReservationStore store;

    public RatePlanReport(ReservationStore store) {
        this.store = store;
    }

    public String generate(YearMonth month) {
        List<Reservation> withRevenue = new ArrayList<>();
        for (Reservation reservation : store.all()) {
            boolean keptMoney = reservation.amountKept().signum() > 0;
            if (keptMoney && YearMonth.from(reservation.checkIn()).equals(month)) {
                withRevenue.add(reservation);
            }
        }

        List<String> rows = new ArrayList<>();
        int totalCount = 0;
        BigDecimal totalAmount = PriceCalculator.cents(BigDecimal.ZERO);
        for (RatePlan plan : RatePlan.values()) {
            int count = 0;
            BigDecimal amount = PriceCalculator.cents(BigDecimal.ZERO);
            for (Reservation reservation : withRevenue) {
                if (reservation.ratePlan() == plan) {
                    count++;
                    amount = amount.add(reservation.amountKept());
                }
            }
            rows.add(plan + "," + count + "," + amount.toPlainString());
            totalCount += count;
            totalAmount = totalAmount.add(amount);
        }
        return CsvReport.render("rate-plans", month.toString(), "rate_plan,reservations,amount", rows,
                "total," + totalCount + "," + totalAmount.toPlainString());
    }
}
EOF
